-- Apply after the admin migration. Seeds existing case studies without overwriting edits.
create table if not exists public.portfolio_projects (
 slug text primary key check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) between 3 and 120),
 data jsonb not null check(jsonb_typeof(data)='object'),
 created_at timestamptz not null default now()
);
alter table public.portfolio_projects enable row level security;
revoke all on public.portfolio_projects from anon, authenticated;
grant select on public.portfolio_projects to anon, authenticated;
grant insert,update,delete on public.portfolio_projects to authenticated;
drop policy if exists public_read_projects on public.portfolio_projects;
create policy public_read_projects on public.portfolio_projects for select to anon,authenticated using(true);
drop policy if exists admin_manage_projects on public.portfolio_projects;
create policy admin_manage_projects on public.portfolio_projects for all to authenticated using(exists(select 1 from public.admin_members where user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_members where user_id=(select auth.uid())));
insert into public.portfolio_projects(slug,data) values ('ecoroute', '{"slug":"ecoroute","name":"EcoRoute","category":"Geospatial engineering","title":"Better routes. A lighter footprint.","description":"An eco-routing engine that brings graph-based pathfinding, crowdsourced traffic, and topographical context into one transit experience.","stack":["FastAPI","React-Leaflet","Supabase","PostgreSQL"],"color":"green","challenge":"The shortest path does not always reflect the conditions on the road. Routing needs to account for changing traffic and terrain while keeping the experience understandable.","approach":"Represent the transit network as a weighted graph, combine traffic observations with topographical inputs, and expose route alternatives through a geospatial interface.","features":["Graph-based route calculation","Crowdsourced traffic observations","Topographical route weighting","Interactive map and route alternatives"],"nodes":[{"title":"Map experience","tech":"React · React-Leaflet","detail":"Displays route alternatives and map layers, and captures origin and destination input."},{"title":"Routing engine","tech":"Python · FastAPI","detail":"Combines graph weights, traffic observations, and terrain parameters to calculate candidate routes."},{"title":"Geospatial data","tech":"Supabase · PostgreSQL","detail":"Stores transit graph data and observations behind controlled database access."}]}') on conflict do nothing;
insert into public.portfolio_projects(slug,data) values ('fleet-command', '{"slug":"fleet-command","name":"Fleet Command","category":"Enterprise logistics","title":"One command center. Every vehicle.","description":"A fleet operations platform connecting live vehicle positions, automated dispatch, route history, and maintenance scheduling.","stack":["Next.js","Node.js","WebSockets","Redis","PostgreSQL"],"color":"blue","challenge":"Dispatchers need a coherent view of moving vehicles, driver activity, and maintenance commitments without stitching together separate tools.","approach":"Separate durable operational records from transient location events. Stream vehicle updates to a dispatch interface while retaining the history needed for reporting.","features":["Live GPS vehicle tracking","Automated dispatch workflows","Driver route history","Maintenance scheduling dashboards"],"nodes":[{"title":"Operations console","tech":"Next.js · React","detail":"Gives dispatchers a shared view of vehicle positions, assignments, and scheduled maintenance."},{"title":"Event pipeline","tech":"Node.js · WebSockets · Redis","detail":"Processes incoming location events and distributes updates to connected operations clients."},{"title":"Fleet records","tech":"PostgreSQL","detail":"Persists dispatch assignments, route history, and maintenance records."}]}') on conflict do nothing;
insert into public.portfolio_projects(slug,data) values ('isp-billing', '{"slug":"isp-billing","name":"ISP Billing Gateway","category":"Network infrastructure","title":"From payment to connected.","description":"An automated subscriber gateway connecting M-Pesa billing, MikroTik access policies, and real-time PPPoE and Hotspot session tracking.","stack":["MikroTik API","M-Pesa Daraja","PPPoE","Hotspot"],"color":"purple","challenge":"Subscriber payments and network access must stay in sync, even when callbacks are delayed or a gateway is temporarily unavailable.","approach":"Treat payment confirmation and provisioning as separate, traceable steps. Reconcile billing events before applying access and bandwidth policies through the MikroTik API.","features":["M-Pesa STK push billing","Automated subscriber provisioning","Dynamic bandwidth policies","Real-time session tracking"],"nodes":[{"title":"Subscriber portal","tech":"Billing · Session management","detail":"Lets subscribers initiate payments and gives operators visibility into plans and sessions."},{"title":"Payment orchestration","tech":"M-Pesa Daraja API","detail":"Reconciles payment callbacks with subscriber accounts before requesting access changes."},{"title":"Network access","tech":"MikroTik · PPPoE · Hotspot","detail":"Applies subscriber access and bandwidth policies, and reports session state."}]}') on conflict do nothing;
